use std::f64::consts::PI;

// ---- Trait definitions ----
trait Shape {
    fn area(&self) -> f64;
    fn perimeter(&self) -> f64;
    fn description(&self) -> String;
}

// ---- Circle ----
struct Circle {
    radius: f64,
}

impl Circle {
    fn new(radius: f64) -> Self {
        Circle { radius }
    }
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        PI * self.radius * self.radius
    }

    fn perimeter(&self) -> f64 {
        2.0 * PI * self.radius
    }

    fn description(&self) -> String {
        format!("Circle with radius {:.2}", self.radius)
    }
}

// ---- Rectangle ----
struct Rectangle {
    width: f64,
    height: f64,
}

impl Rectangle {
    fn new(width: f64, height: f64) -> Self {
        Rectangle { width, height }
    }
}

impl Shape for Rectangle {
    fn area(&self) -> f64 {
        self.width * self.height
    }

    fn perimeter(&self) -> f64 {
        2.0 * (self.width + self.height)
    }

    fn description(&self) -> String {
        format!("Rectangle {}x{}", self.width, self.height)
    }
}

// ---- Triangle ----
struct Triangle {
    a: f64,
    b: f64,
    c: f64,
}

impl Triangle {
    fn new(a: f64, b: f64, c: f64) -> Self {
        Triangle { a, b, c }
    }
}

impl Shape for Triangle {
    fn area(&self) -> f64 {
        // Heron's formula
        let s = (self.a + self.b + self.c) / 2.0;
        (s * (s - self.a) * (s - self.b) * (s - self.c)).sqrt()
    }

    fn perimeter(&self) -> f64 {
        self.a + self.b + self.c
    }

    fn description(&self) -> String {
        format!("Triangle with sides {:.2}, {:.2}, {:.2}", self.a, self.b, self.c)
    }
}

// ---- Square (newtype) ----
struct Square {
    side: f64,
}

impl Square {
    fn new(side: f64) -> Self {
        Square { side }
    }
}

impl Shape for Square {
    fn area(&self) -> f64 {
        self.side * self.side
    }

    fn perimeter(&self) -> f64 {
        4.0 * self.side
    }

    fn description(&self) -> String {
        format!("Square with side {:.2}", self.side)
    }
}

// ---- Function that works with any Shape ----
fn print_shape_info(shape: &impl Shape) {
    println!("--- {} ---", shape.description());
    println!("Area: {:.2}", shape.area());
    println!("Perimeter: {:.2}", shape.perimeter());
    println!();
}

// ---- Find the shape with the largest area ----
fn largest_area<'a>(shapes: &'a [&'a dyn Shape]) -> &'a dyn Shape {
    let mut largest = shapes[0];
    for shape in shapes {
        if shape.area() > largest.area() {
            largest = *shape;
        }
    }
    largest
}

fn main() {
    // ---- Create shapes ----
    let circle = Circle::new(5.0);
    let rectangle = Rectangle::new(4.0, 6.0);
    let triangle = Triangle::new(3.0, 4.0, 5.0);
    let square = Square::new(3.5);

    // ---- Print each shape ----
    println!("=== Shape Calculator ===\n");

    print_shape_info(&circle);
    print_shape_info(&rectangle);
    print_shape_info(&triangle);
    print_shape_info(&square);

    // ---- Store shapes in a vector ----
    let shapes: Vec<&dyn Shape> = vec![&circle, &rectangle, &triangle, &square];

    // ---- Find the largest shape ----
    let largest = largest_area(&shapes);
    println!("=== Largest Shape ===");
    println!("{} has the largest area: {:.2}", largest.description(), largest.area());

    // ---- Calculate total area ----
    let total_area: f64 = shapes.iter().map(|s| s.area()).sum();
    println!("\nTotal area of all shapes: {:.2}", total_area);
}

